SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(6*10^9);Alarm(850);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");load "work/deg10/continuation_20261031b/C54/inputs/pair_af_place_linear.m";root:="work/deg10/continuation_20261031b/C54/";a:=eval Read(root cat "dyadic_rigidity_v2.m");X:=MDX1(27,GF(2));C:=Curve(X);F0,mp:=AlgorithmicFunctionField(FunctionField(C));F:=RationalExtensionRepresentation(F0);assert Genus(F)eq 13;k:=GF(2);PK:=PolynomialRing(k);xy:=[F!mp(v):v in X`_coordinates_xy];cs:=Cusps(X);sigs:=[CuspSignature(X,p):p in cs];cp:=[Support(FunctionFieldDivisor(Divisor(cs[Index(sigs,sg)])))[1]:sg in a[3]];assert [Degree(p):p in cp]eq a[4];A:=Divisor(cp[Index(a[4],1)]);G,_,phi:=ClassGroup(F:ReductionDivisor:=A,Proof:=true);assert Invariants(G)eq[3,3,52497,0];cg:=[phi(Divisor(p)-Degree(p)*A):p in cp];Gold:=AbelianGroup([3,3,52497]);Z:=FreeAbelianGroup(#cp);hOld:=hom<Z->Gold|[Gold!v[1..3]:v in a[6]]>;hNew:=hom<Z->G|cg>;assert #Image(hOld)eq 472473 and #Image(hNew)eq 472473;cv:=hom<Gold->G|[hNew(Gold.i@@hOld):i in[1..3]]>;assert #Image(cv)eq 472473 and &and[cv(hOld(Z.i))eq cg[i]:i in[1..#cp]];
ns:=AssociativeArray();for r in a[9]do d,ni:=Explode([r[1],r[2]]);K:=ext<k|PK!r[3]>;v:=[Evaluate(PK!w,K.1):w in r[4]];assert #v eq 3 and v[3]ne 0;vals:=[v[1]/v[3],v[2]/v[3]];p:=C48PairAFPlaceLinear(xy,vals);assert Degree(p)eq d;ns[[d,ni]]:=p;end for;assert #ns eq 25;obs:=[* *];left:=[];
for r in a[7]do id,d,ni,ca,ce,hh,c0,c1:=Explode(r);N:=Divisor(ns[[d,ni]]);v:=[ca[j]+ce[j]:j in[1..#cp]];for j in[1..#cp]do v[a[5][j]]+:=ce[j];end for;D:=N+&+[v[j]*Divisor(cp[j]):j in[1..#cp]];h:=#Basis(D);assert h eq hh;g0:=phi(N-d*A)+&+[(ca[j]+ce[j])*cg[j]:j in[1..#cp]];g1:=phi(N-d*A)+&+[ca[j]*cg[j]+ce[j]*cg[a[5][j]]:j in[1..#cp]];assert g0 eq cv(Gold!c0[1..3])and g1 eq cv(Gold!c1[1..3]);if h gt 1 then Append(~left,id);end if;Append(~obs,[*id,h,Eltseq(g0),Eltseq(g1)*]);if id mod 500 eq 0 then print "D31B_C54_PARENT_DYADIC_PROGRESS",id,#left,Cputime(tt);end if;end for;
assert left eq[r[1]:r in a[8]];Write(root cat "parent_dyadic_replay.m",Sprint([*[Genus(F),#ns,#obs,#obs-#left,#left],obs*]):Overwrite:=true);print "D31B_C54_PARENT_DYADIC_COMPLETE",#obs,#left,#Image(cv),Cputime(tt);quit;
